
(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const DB = () => window.db || (typeof db !== 'undefined' ? db : null);
  const USER = () => window.currentUser || (typeof currentUser !== 'undefined' ? currentUser : null);
  const CHATS = () => (typeof conversations !== 'undefined' ? conversations : (window.conversations || []));
  const esc = v => String(v ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const say = m => (window.toast || window.notify || window.notifyMsg || console.info)(String(m ?? 'Неизвестная ошибка'));
  const errText = e => e?.message || e?.error_description || String(e || 'Неизвестная ошибка');
  const when = v => v ? new Date(v).toLocaleString('ru-RU') : '—';
  const publishableKey = typeof SUPABASE_KEY !== 'undefined' ? SUPABASE_KEY : '';
  const supabaseUrl = typeof SUPABASE_URL !== 'undefined' ? SUPABASE_URL : 'https://xxvcsaomkyknudoaixbs.supabase.co';
// -------------------- Admin panel: user filters, analytics, notices, RIM ID --------------------
  let adminUserMode='hidden',adminUserQuery='';
  async function adminUsersLoad(){const d=DB(),out=$('rimAdminUsersList');if(!d||!out)return;out.innerHTML='<div class="rim-update-muted">Загрузка пользователей…</div>';let result;if(adminUserMode==='all')result=await d.rpc('rim_admin_list_users',{p_limit:150,p_offset:0});else if(adminUserMode==='search'){if(adminUserQuery.length<2){out.innerHTML='<div class="rim-update-muted">Введите минимум два символа для поиска.</div>';return;}result=await d.rpc('rim_admin_search_users',{p_query:adminUserQuery,p_limit:100});}else{out.innerHTML='<div class="rim-update-muted">Список пользователей скрыт.</div>';return;}if(result.error){out.innerHTML=`<div class="notice">${esc(errText(result.error))}</div>`;return;}out.innerHTML=(result.data||[]).map(x=>`<div class="rim-admin-user"><div><b>${esc(x.display_name||x.username||'Пользователь')}</b><small>@${esc(x.username||'—')} · ${esc(x.email||'email скрыт')}</small><small>Регистрация: ${when(x.created_at)} · Вход: ${when(x.last_sign_in_at)}</small><small>Последняя активность: ${when(x.last_seen_at)}</small><small>ID: ${esc(x.user_id)}</small></div><div class="rim-admin-user-actions"><select class="field" id="rimRole-${x.user_id}"><option value="user" ${x.role==='user'?'selected':''}>Пользователь</option><option value="moderator" ${x.role==='moderator'?'selected':''}>Модератор</option><option value="admin" ${x.role==='admin'?'selected':''}>Администратор</option><option value="superadmin" ${x.role==='superadmin'?'selected':''}>Суперадмин</option></select><button class="action-btn" onclick="rimAdminSetRole('${x.user_id}')">Роль</button><button class="action-btn" onclick="rimAdminShowUserSessions('${x.user_id}')">Сеансы</button></div></div>`).join('')||'<div class="empty-state">Пользователи не найдены.</div>';}
  if(window.__RIM_ADMIN_COMMANDS_OWNED){/* modular owns admin */}else window.rimAdminUsersMode=async mode=>{adminUserMode=mode;if(mode==='all')adminUserQuery='';if(mode==='hidden'){$('rimAdminUsersList').innerHTML='<div class="rim-update-muted">Список скрыт.</div>';return;}await adminUsersLoad();};
  if(window.__RIM_ADMIN_COMMANDS_OWNED){}else window.rimAdminUsersSearch=async()=>{adminUserMode='search';adminUserQuery=$('rimAdminUserSearch')?.value.trim().replace(/^@/,'')||'';await adminUsersLoad();};
  if(window.__RIM_ADMIN_COMMANDS_OWNED){}else window.rimLoadAdminUsers=adminUsersLoad;
  window.rimAdminSetRole=async id=>{const role=$('rimRole-'+id)?.value;const {error}=await DB().rpc('rim_admin_update_user_role',{p_user_id:id,p_role:role});if(error)return say(errText(error));say('Роль изменена.');await adminUsersLoad();};
  if(window.__RIM_ADMIN_COMMANDS_OWNED){}else window.rimAdminShowUserSessions=async userId=>{const {data,error}=await DB().rpc('rim_admin_list_sessions',{p_user_id:userId});if(error)return say(errText(error));window.showModal(`<h2 class="modal-title">Активные сеансы пользователя</h2>${(data||[]).map(s=>`<div class="rim-group-member"><div><b>${esc(s.display_name||s.username||s.email||'Пользователь')}</b><div class="rim-update-muted">${esc(s.user_agent||'Устройство неизвестно')}</div><div class="rim-update-muted">IP: ${esc(s.ip||'—')} · Активность: ${when(s.updated_at)}</div></div><button class="action-btn danger-btn" onclick="rimAdminRevokeSession('${s.session_id}')">Завершить</button></div>`).join('')||'<div class="empty-state">Активных сеансов нет.</div>'}`);};
  if(window.__RIM_ADMIN_COMMANDS_OWNED){}else window.rimAdminRevokeSession=async id=>{if(!confirm('Завершить сеанс?'))return;const {error}=await DB().rpc('rim_admin_revoke_session',{p_session_id:id});if(error)return say(errText(error));say('Сеанс завершён.');window.closeModal?.();};
  if(window.__RIM_ADMIN_COMMANDS_OWNED){}else window.rimLoadStats=async()=>{const out=$('rimStats');if(!out)return;const [stats,series]=await Promise.all([DB().rpc('rim_admin_dashboard_stats'),DB().rpc('rim_admin_analytics_timeseries',{p_days:14})]);if(stats.error){out.innerHTML=`<div class="notice">${esc(errText(stats.error))}</div>`;return;}const data=stats.data||{},items=[['Аккаунты',data.users_total],['Активны за 24 часа',data.users_active_24h],['Активные сеансы',data.sessions_active],['Сеансы за 24 часа',data.sessions_24h],['Каналы',data.channels_total],['Группы',data.groups_total],['Личные чаты',data.direct_chats_total],['Сообщения',data.messages_total],['Комментарии',data.comments_total],['Опросы',data.polls_total],['Голоса',data.poll_votes_total],['Новые жалобы',data.reports_new],['Рекламные кампании',data.ads_total],['Показы рекламы за 24 ч.',data.ad_impressions_24h],['Переходы за 24 ч.',data.ad_clicks_24h],['События аналитики за 24 ч.',data.events_24h],['Оплачено по договорам',Number(data.paid_contracts_total||0).toLocaleString('ru-RU')+' ₽']];const rows=series.error?[]:(series.data||[]);window.__rimAnalyticsRows=rows;const ctr=Number(data.ad_impressions_24h||0)?(Number(data.ad_clicks_24h||0)*100/Number(data.ad_impressions_24h||0)).toFixed(1)+'%':'—';items.push(['CTR рекламы за 24 ч.',ctr]);out.innerHTML='<div class="rim-admin-metrics">'+items.map(([k,v])=>`<div class="rim-admin-metric"><span>${esc(k)}</span><b>${esc(v??0)}</b></div>`).join('')+'</div><div class="row" style="margin-top:16px;flex-wrap:wrap"><h4 class="grow" style="margin:0">Динамика · 14 дней</h4><select class="field" id="rimAnalyticsMetric" onchange="rimRenderAnalyticsSeries(this.value)"><option value="active_users">Активные пользователи</option><option value="registrations">Регистрации</option><option value="messages">Сообщения</option><option value="comments">Комментарии</option><option value="channel_views">Просмотры каналов</option><option value="ad_impressions">Показы рекламы</option><option value="ad_clicks">Переходы по рекламе</option><option value="poll_votes">Голоса в опросах</option></select></div><div id="rimAnalyticsChart" class="rim-analytics-days"></div><p class="rim-update-muted">Сводка строится по реальным событиям, сообщениям, комментариям, опросам и рекламным показам.</p>';window.rimRenderAnalyticsSeries('active_users');};
  window.rimRenderAnalyticsSeries=metric=>{const out=$('rimAnalyticsChart'),rows=window.__rimAnalyticsRows||[];if(!out)return;const max=Math.max(1,...rows.map(x=>Number(x[metric]||0)));out.innerHTML=rows.map(x=>`<div class="rim-analytics-day"><span>${new Date(x.day+'T00:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'})}</span><div class="rim-analytics-bar"><i style="width:${Math.max(0,Math.min(100,Number(x[metric]||0)*100/max))}%"></i></div><b>${x[metric]||0}</b></div>`).join('')||'<div class="rim-update-muted">Пока нет данных.</div>';};
  window.rimAdminSendNotice=async()=>{const raw=$('rimNoticeUsername')?.value.trim().replace(/^@/,'')||'',title=$('rimNoticeTitle')?.value.trim(),body=$('rimNoticeBody')?.value.trim();if(!title||!body)return say('Заполните заголовок и текст обращения.');let userId=null;if(raw){const {data,error}=await DB().from('profiles').select('id').eq('username',raw).maybeSingle();if(error||!data)return say('Пользователь с таким username не найден.');userId=data.id;}const {data,error}=await DB().rpc('rim_admin_send_notice',{p_user_id:userId,p_title:title,p_body:body});if(error)return say(errText(error));say(`Обращение отправлено: ${data} получателей.`);$('rimNoticeUsername').value='';$('rimNoticeTitle').value='';$('rimNoticeBody').value='';};

  async function rimIdRequest(path,method='GET',body=null){const d=DB(),{data:s,error}=await d.auth.getSession();if(error||!s?.session?.access_token)throw new Error('Не удалось получить активную сессию.');const headers={'Authorization':'Bearer '+s.session.access_token,'apikey':publishableKey};if(body)headers['Content-Type']='application/json';const res=await fetch(supabaseUrl+'/functions/v1/rim-id/'+path,{method,headers,body:body?JSON.stringify(body):undefined});const json=await res.json().catch(()=>({error:'invalid_response'}));if(!res.ok)throw new Error(json.detail||json.error||`HTTP ${res.status}`);return json;}
  window.rimIdLoadClients=async()=>{const out=$('rimIdClientsList');if(!out)return;out.innerHTML='<div class="rim-update-muted">Загружаем приложения…</div>';try{const data=await rimIdRequest('admin');out.innerHTML=(data.clients||[]).map(c=>`<article class="rim-update-card"><div class="row"><b class="grow">${esc(c.client_name)}</b><span class="badge">${c.enabled?'Активно':'Отключено'}</span></div><div class="rim-update-muted">ID: ${esc(c.client_id)}</div><div class="rim-update-muted">Тип: ${esc(c.client_type)} · Redirect URI: ${esc((c.redirect_uris||[]).join(', '))}</div><div class="rim-update-muted">Разрешения: ${esc((c.allowed_scopes||[]).join(', '))}</div><div class="row" style="margin-top:8px"><button class="action-btn" onclick="rimIdSetClient('${esc(c.client_id)}',${!c.enabled})">${c.enabled?'Отключить':'Включить'}</button><button class="action-btn danger-btn" onclick="rimIdDeleteClient('${esc(c.client_id)}')">Удалить</button></div></article>`).join('')||'<div class="empty-state">Внешних приложений пока нет.</div>';}catch(e){out.innerHTML=`<div class="notice">Не удалось загрузить РИМ ID: ${esc(errText(e))}</div>`;}};
  window.rimIdCreateClient=async()=>{const name=$('rimIdClientName')?.value.trim(),redirects=($('rimIdRedirects')?.value||'').split('\n').map(x=>x.trim()).filter(Boolean),type=$('rimIdClientType')?.value||'public';if(!name||!redirects.length)return say('Укажите название и хотя бы один Redirect URI.');try{const r=await rimIdRequest('admin','POST',{action:'create',client_name:name,redirect_uris:redirects,client_type:type});window.showModal(`<h2 class="modal-title">Приложение зарегистрировано</h2><p>Сохраните Client ID. Секрет для confidential-клиента показывается только сейчас.</p><label>Client ID</label><input class="field" readonly value="${esc(r.client_id)}"><button class="action-btn" onclick="navigator.clipboard.writeText('${esc(r.client_id)}')">Копировать ID</button>${r.client_secret?`<label>Client Secret</label><input class="field" readonly value="${esc(r.client_secret)}"><button class="action-btn" onclick="navigator.clipboard.writeText('${esc(r.client_secret)}')">Копировать секрет</button>`:''}<p class="rim-update-muted">Не публикуйте секрет в браузерном коде. Для мобильных и SPA-клиентов используйте тип public и PKCE.</p><button class="primary-btn" onclick="closeModal();rimIdLoadClients()">Готово</button>`);$('rimIdClientName').value='';$('rimIdRedirects').value='';}catch(e){say('Не удалось создать приложение: '+errText(e));}};

  window.rimIdSetClient=async(id,enabled)=>{try{await rimIdRequest('admin','POST',{action:'set_enabled',client_id:id,enabled});await rimIdLoadClients();}catch(e){say(errText(e));}};
  window.rimIdDeleteClient=async id=>{if(!confirm('Удалить интеграцию РИМ ID?'))return;try{await rimIdRequest('admin','POST',{action:'delete',client_id:id});await rimIdLoadClients();}catch(e){say(errText(e));}};
  window.__rimIdPending=null;
  window.rimIdHandleAuthorizeRequest=async()=>{
    if(window.__rimIdConsentShown)return;
    const params=new URLSearchParams(window.location.search||'');if(params.get('rim_id_authorize')!=='1')return;
    const clientId=params.get('client_id')||'',redirectUri=params.get('redirect_uri')||'',challenge=params.get('code_challenge')||'',state=params.get('state')||'',nonce=params.get('nonce')||'',scopes=(params.get('scope')||'openid profile').split(/[ ,]+/).filter(Boolean);
    if(!clientId||!redirectUri||!/^[A-Za-z0-9_-]{43,128}$/.test(challenge)){say('Запрос РИМ ID некорректен: отсутствует Client ID, Redirect URI или PKCE challenge.');return;}
    const sessionResult=await DB()?.auth.getSession();const session=sessionResult?.data?.session;if(!session?.access_token){say('Чтобы подтвердить вход через РИМ ID, сначала войдите в свой аккаунт РИМа. После входа запрос появится снова.');return;}
    const infoUrl=supabaseUrl+'/functions/v1/rim-id/client?'+new URLSearchParams({client_id:clientId,redirect_uri:redirectUri});
    const infoRes=await fetch(infoUrl,{headers:{apikey:publishableKey}});const info=await infoRes.json().catch(()=>({}));if(!infoRes.ok){say('РИМ ID отклонил запрос приложения: '+(info.error||'проверьте настройки интеграции'));return;}
    const allowed=(info.allowed_scopes||[]),requested=[...new Set(scopes.filter(x=>allowed.includes(x)))];if(!requested.includes('openid'))requested.unshift('openid');
    window.__rimIdPending={clientId,redirectUri,challenge,state,nonce,scopes:requested,accessToken:session.access_token};window.__rimIdConsentShown=true;
    const labels={openid:'Подтверждение личности через РИМ ID',profile:'Имя пользователя, отображаемое имя и аватар',email:'Адрес электронной почты', 'messenger.read':'Чтение доступных вам переписок','messenger.write':'Создание переписок и отправка сообщений'};
    window.showModal(`<div style="max-height:78vh;overflow:auto"><div class="rim-update-card"><div class="rim-update-muted">ЗАПРОС АВТОРИЗАЦИИ</div><h2 style="margin:6px 0">${esc(info.client_name||'Внешнее приложение')}</h2><p>Это приложение запрашивает доступ к вашему аккаунту РИМа.</p><div class="rim-update-muted">Перенаправление: ${esc(redirectUri)}</div></div><h3>Запрашиваемые разрешения</h3>${requested.map(x=>`<div class="rim-group-member"><span>${esc(labels[x]||x)}</span><span class="badge">${esc(x)}</span></div>`).join('')}<p class="rim-update-muted">Разрешение будет выдано только после вашего подтверждения. Вы сможете отозвать его в настройках аккаунта → Подключённые приложения РИМ ID.</p><div class="row" style="margin-top:12px"><button class="primary-btn grow" onclick="rimIdApproveRequest()">Разрешить</button><button class="action-btn danger-btn" onclick="rimIdDenyRequest()">Отклонить</button></div></div>`);
  };
  window.rimIdApproveRequest=async()=>{const p=window.__rimIdPending;if(!p)return;try{const res=await fetch(supabaseUrl+'/functions/v1/rim-id/authorize',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+p.accessToken,'apikey':publishableKey},body:JSON.stringify({client_id:p.clientId,redirect_uri:p.redirectUri,code_challenge:p.challenge,code_challenge_method:'S256',scopes:p.scopes,nonce:p.nonce,state:p.state})});const data=await res.json().catch(()=>({}));if(!res.ok||!data.redirect_to)throw new Error(data.error||'Не удалось выдать код авторизации.');window.location.assign(data.redirect_to);}catch(e){say('Ошибка РИМ ID: '+errText(e));}};
  window.rimIdDenyRequest=()=>{const p=window.__rimIdPending;if(!p)return;const target=new URL(p.redirectUri);target.searchParams.set('error','access_denied');if(p.state)target.searchParams.set('state',p.state);window.location.assign(target.toString());};
  const baseInitializeForRimId=window.initializeApp;if(typeof baseInitializeForRimId==='function')window.initializeApp=async function(){const r=await baseInitializeForRimId.apply(this,arguments);setTimeout(()=>window.rimIdHandleAuthorizeRequest().catch(e=>say(errText(e))),250);return r;};
  try{DB()?.auth.onAuthStateChange((event,session)=>{if(session?.access_token)setTimeout(()=>window.rimIdHandleAuthorizeRequest().catch(e=>say(errText(e))),350);});}catch(_){}
  window.addEventListener?.('load',()=>setTimeout(()=>window.rimIdHandleAuthorizeRequest().catch(e=>say(errText(e))),450));

  window.rimIdDeleteClient=async id=>{if(!confirm('Удалить интеграцию РИМ ID?'))return;try{await rimIdRequest('admin','POST',{action:'delete',client_id:id});await rimIdLoadClients();}catch(e){say(errText(e));}};
  const baseAdmin=window.rimAdmin;
  if(typeof baseAdmin==='function')window.rimAdmin=async function(){await baseAdmin.apply(this,arguments);const body=$('rimFullPage')?.querySelector('.rim-page-body');if(!body)return;
    let users=$('rimAdminUsersCard');if(!users){users=document.createElement('section');users.id='rimAdminUsersCard';users.className='rim-update-card';body.prepend(users);}users.innerHTML=`<h3 style="margin-top:0">Пользователи</h3><div class="row" style="flex-wrap:wrap"><button class="action-btn" onclick="rimAdminUsersMode('all')">Показать всех</button><button class="action-btn" onclick="rimAdminUsersMode('search')">Поиск по username</button><button class="action-btn" onclick="rimAdminUsersMode('hidden')">Скрыть список</button></div><div class="rim-search-panel" style="margin-top:9px"><input id="rimAdminUserSearch" class="field" placeholder="@username, имя или email"><button class="primary-btn" onclick="rimAdminUsersSearch()">Найти</button></div><div id="rimAdminUsersList" style="margin-top:8px">Список скрыт.</div>`;
    const oldStats=$('rimStats');if(oldStats&&!oldStats.closest('#rimAdminAnalyticsCard'))oldStats.closest('.card')?.remove();let analytics=$('rimAdminAnalyticsCard');if(!analytics){analytics=document.createElement('section');analytics.id='rimAdminAnalyticsCard';analytics.className='rim-update-card';body.appendChild(analytics);}analytics.innerHTML='<div class="row"><h3 class="grow" style="margin:0">Аналитика РИМа</h3><button class="action-btn" onclick="rimLoadStats()">Обновить</button></div><div id="rimStats"></div>';
    let notices=$('rimAdminNoticeCard');if(!notices){notices=document.createElement('section');notices.id='rimAdminNoticeCard';notices.className='rim-update-card';body.appendChild(notices);}notices.innerHTML=`<h3 style="margin-top:0">Обращения и приветственные сообщения</h3><p class="rim-update-muted">Оставьте поле username пустым, чтобы отправить уведомление всем аккаунтам. Это внутренняя рассылка РИМа, не email.</p><input id="rimNoticeUsername" class="field" placeholder="@username — необязательно"><input id="rimNoticeTitle" class="field" maxlength="120" placeholder="Заголовок" style="margin-top:7px"><textarea id="rimNoticeBody" class="field" rows="4" maxlength="3000" placeholder="Текст обращения" style="margin-top:7px"></textarea><button class="primary-btn" style="margin-top:8px" onclick="rimAdminSendNotice()">Отправить уведомление</button>`;
    let idcard=$('rimIdAdminCard');if(!idcard){idcard=document.createElement('section');idcard.id='rimIdAdminCard';idcard.className='rim-update-card';body.appendChild(idcard);}idcard.innerHTML=`<h3 style="margin-top:0">РИМ ID · управление приложениями</h3><p class="rim-update-muted">Регистрация внешних приложений, Redirect URI, разрешения, включение и отключение интеграций. Авторизация использует серверный Edge Function rim-id и PKCE.</p><input id="rimIdClientName" class="field" maxlength="80" placeholder="Название приложения"><textarea id="rimIdRedirects" class="field" rows="3" placeholder="https://example.com/callback — каждый адрес с новой строки" style="margin-top:7px"></textarea><select id="rimIdClientType" class="field" style="margin-top:7px"><option value="public">Public · мобильное приложение / SPA · PKCE</option><option value="confidential">Confidential · серверное приложение</option></select><button class="primary-btn" style="margin-top:8px" onclick="rimIdCreateClient()">Зарегистрировать приложение</button><div class="row" style="margin-top:10px"><h4 class="grow">Подключённые приложения</h4><button class="action-btn" onclick="rimIdLoadClients()">Обновить</button></div><div id="rimIdClientsList"></div>`;
    await window.rimAdminUsersMode('hidden');await window.rimLoadStats();await window.rimIdLoadClients();
  };
})();

